460	/// Ablation: run each candidate strategy in place of step 5 and score it.
461	fn ablation(cps: &[Checkpoint]) {
462	    let g = graph_impact();
463	    let cases = eval_set();
464	    let find = |sha:&str| cps.iter().find(|c| c.commit_sha==sha).unwrap();
465	
466	    type Strat = (&'static str, fn(&str,&Checkpoint)->Option<(f32,String)>);
467	    let strats: Vec<Strat> = vec![
468	        ("A diff-grounded", strat_diff),
469	        ("B graph spread",  strat_spread),
470	        ("C domain lexicon",strat_lexicon),
471	        ("D 4-gram cosine", strat_ngram),
472	    ];
473	
474	    println!("── ablation: which strategy closes the paraphrase gap?\n");
475	    println!("   {:<18} {:>5} {:>7} {:>7} {:>7} {:>9}", "strategy", "acc", "para", "contra-P", "contra-R", "µs/verdict");
476	
477	    // baseline: current fused pipeline, no step-5 rescue
478	    let mut rows = Vec::new();
479	    for (name, f) in std::iter::once(("— none (current)", none_strat as fn(&str,&Checkpoint)->Option<(f32,String)>)).chain(strats.into_iter()) {
480	        let preds: Vec<(Agree,Agree)> = cases.iter().map(|c| {
481	            let cp = find(c.sha);
482	            let (mut v, _) = agreement(c.claim, cp, &g);
483	            if v == Agree::Neutral { if f(c.claim, cp).is_some() { v = Agree::Corroborated; } }
484	            (v, c.truth)
485	        }).collect();
486	        let acc = preds.iter().filter(|(p,t)| p==t).count() as f32 / preds.len() as f32;
487	        let para: Vec<usize> = cases.iter().enumerate().filter(|(_,c)| c.note=="paraphrase").map(|(i,_)| i).collect();
488	        let pacc = para.iter().filter(|i| preds[**i].0==preds[**i].1).count() as f32 / para.len() as f32;
489	        let tp = preds.iter().filter(|(p,t)| *p==Agree::Contradicted && *t==Agree::Contradicted).count() as f32;
490	        let fp = preds.iter().filter(|(p,t)| *p==Agree::Contradicted && *t!=Agree::Contradicted).count() as f32;
491	        let fnn= preds.iter().filter(|(p,t)| *p!=Agree::Contradicted && *t==Agree::Contradicted).count() as f32;
492	        let pr = if tp+fp>0.0 {tp/(tp+fp)} else {0.0};
493	        let rc = if tp+fnn>0.0 {tp/(tp+fnn)} else {0.0};
