4	#[derive(Deserialize, Clone)]
5	struct Case { sha: String, msg: String, mutated: String, files: Vec<String>, diff: String, label: u8, mtype: String }
6	
7	const STOP: &[&str] = &["the","a","an","and","or","to","of","in","is","it","this","that","we","you",
8	 "for","on","with","not","be","are","was","so","at","as","its","into","from","by","must","now","their","own","when"];
