60	// ══════════ RECALL MECHANISMS ══════════
61	
62	/// Split a diff into added / removed vocabularies, kept separate so we can
63	/// check not just WHETHER a symbol is in the change but on WHICH SIDE.
64	fn signed_vocab(c:&Case)->(HashSet<String>,HashSet<String>){
65	 let (mut add,mut rem)=(HashSet::new(),HashSet::new());
66	 for line in c.diff.lines(){
67	  let plus=line.starts_with('+') && !line.starts_with("+++");
68	  let minus=line.starts_with('-') && !line.starts_with("---");
69	  if !plus && !minus {continue;}
70	  for tok in line.split(|ch:char| !ch.is_alphanumeric() && ch!='_'){
71	   for p in split_ident(tok){
72	    if p.len()>3 && !STOP.contains(&p.as_str()){
73	     if plus {add.insert(p);} else {rem.insert(p);}
74	    }
75	   }
76	  }
77	 }
78	 (add,rem)
79	}
80	
81	/// M1 — IDENTIFIER ANCHORING. Words that LOOK like code (camelCase, snake_case,
82	/// dotted, ()-suffixed, backticked) are hard claims. If the message names one
83	/// and the diff never contains it, the message is lying about the code.
84	fn code_shaped(w:&str)->bool{
85	 let has_upper_inside = w.chars().skip(1).any(|c|c.is_uppercase());
86	 w.contains('_') || w.contains("()") || (w.contains('.') && !w.ends_with('.')) || has_upper_inside
87	}
88	fn m1_identifier_anchor(c:&Case)->Option<bool>{
89	 let v=diff_vocab(c);
90	 let mut checked=false;
91	 for raw in c.mutated.split(|ch:char| ch.is_whitespace()||ch=='`'||ch==','||ch==':'){
92	  let w=raw.trim_matches(|ch:char| !ch.is_alphanumeric() && ch!='_' && ch!='.' && ch!='(' && ch!=')');
93	  if w.len()<5 || !code_shaped(w) {continue;}
94	  checked=true;
95	  let parts=split_ident(w);
96	  if !parts.is_empty() && parts.iter().all(|p| !v.contains(p)) { return Some(true); }
97	 }
98	 if checked {Some(false)} else {None}
99	}
100	
101	/// M2 — SIGNED SYMBOL PLACEMENT. "add X" requires X on a + line; "remove X"
102	/// requires X on a - line. Targets operation_type mismatch directly, which
103	/// unsigned vocabulary checks structurally cannot see.
104	fn m2_signed_placement(c:&Case)->Option<bool>{
105	 let (addv,remv)=signed_vocab(c);
106	 let mp=polarity(&c.mutated);
107	 if mp==0 {return None;}
108	 let mt:Vec<String>=terms(&c.mutated).into_iter().filter(|t|t.len()>4).collect();
109	 let anchored:Vec<&String>=mt.iter().filter(|t| addv.contains(*t)||remv.contains(*t)).collect();
110	 if anchored.is_empty(){return None;}
111	 // does the side the message implies actually contain its subject matter?
112	 let on_add=anchored.iter().filter(|t|addv.contains(**t)).count();
113	 let on_rem=anchored.iter().filter(|t|remv.contains(**t)).count();
114	 let implied_add = mp>0;
115	 // exclusive presence on the WRONG side is the signal
116	 if implied_add && on_add==0 && on_rem>0 {return Some(true);}
117	 if !implied_add && on_rem==0 && on_add>0 {return Some(true);}
118	 Some(false)
119	}
120	
121	/// M3 — IDF ANCHORING. The rarest content word in the message carries the claim.
122	/// Common words ("update","test","error") are noise. If the message's most
123	/// distinctive term is absent from the diff, the claim is unsupported.
124	fn m3_idf_anchor(c:&Case, df:&HashMap<String,usize>, n:usize)->Option<bool>{
125	 let v=diff_vocab(c);
126	 let mt:Vec<String>=terms(&c.mutated).into_iter().filter(|t|t.len()>4).collect();
127	 if mt.is_empty(){return None;}
128	 let mut scored:Vec<(&String,f32)>=mt.iter()
129	   .map(|t|{ let d=*df.get(t).unwrap_or(&1) as f32; (t, (n as f32/d).ln()) }).collect();
130	 scored.sort_by(|a,b| b.1.partial_cmp(&a.1).unwrap());
131	 let top:Vec<&String>=scored.iter().take(2).map(|(t,_)|*t).collect();
132	 Some(top.iter().all(|t| !v.contains(*t)))
133	}
134	
135	/// M4 — SUBTOKEN JACCARD. Word-level identifier overlap, split on case, as a
136	/// less noisy alternative to character n-grams.
137	fn m4_subtoken_jaccard(c:&Case, thresh:f32)->bool{
138	 let v=diff_vocab(c);
139	 let mt:HashSet<String>=terms(&c.mutated).into_iter()
140	   .flat_map(|t| split_ident(&t)).filter(|t|t.len()>3).collect();
141	 if mt.is_empty(){return false;}
142	 let inter=mt.iter().filter(|t|v.contains(*t)).count() as f32;
143	 (inter/mt.len() as f32) < thresh
144	}
