1	//! Semantic agreement: does a claim match what the commit it sits on did?
2	//! Corroboration is earned, not granted for merely sitting on a commit.
3	
4	use crate::graph::GraphReach;
5	use crate::model::Checkpoint;
6	use crate::text::{code_shaped, cosine, diff_vocab, ngrams, polarity, split_ident, terms};
7	
8	/// Three-way verdict of a claim against the commit it sits on.
9	#[derive(PartialEq, Eq, Clone, Copy, Debug, serde::Serialize, serde::Deserialize)]
10	#[serde(rename_all = "lowercase")]
11	pub enum Agree {
12	    Corroborated,
13	    Neutral,
14	    Contradicted,
15	}
16	
17	const ISOLATION: &[&str] = &[
18	    "isolated",
19	    "does not touch",
20	    "nothing else",
21	    "contained",
22	    "no other",
23	];
24	const NGRAM_THRESHOLD: f32 = 0.10;
25	const LEXICAL_MIN_SHARED: usize = 2;
26	
27	/// Checks run in this order; the first that fires decides.
28	pub fn agreement(claim: &str, cp: &Checkpoint, g: &GraphReach) -> (Agree, String) {
29	    let low = claim.to_lowercase();
30	
31	    // 1. Scope: claim asserts isolation, Graph says the blast radius escapes.
32	    if ISOLATION.iter().any(|w| low.contains(w)) {
33	        let reach = g.escapes(&cp.files);
34	        if !reach.is_empty() {
35	            return (
36	                Agree::Contradicted,
37	                format!(
38	                    "claims isolation; Graph reach escapes to {} ({})",
39	                    reach.len(),
40	                    reach.join(", ")
41	                ),
42	            );
43	        }
44	    }
45	
46	    // 2. File: claim names a path the commit never touched. URL segments are
47	    //    not paths: a pasted link must not read as an untouched file.
48	    let claim_terms = terms(claim);
49	    for t in claim_terms
50	        .iter()
51	        .filter(|t| (t.contains('/') || t.ends_with(".go")) && !looks_like_url(t))
52	    {
53	        if !cp
54	            .files
55	            .iter()
56	            .any(|f| f.to_lowercase().contains(t.as_str()))
57	        {
58	            return (
59	                Agree::Contradicted,
60	                format!("references {t} which this commit did not touch"),
61	            );
62	        }
63	    }
64	
65	    // 3. Polarity flip: same topic, opposite action. Conventional-commit
66	    //    prefixes carry polarity the verb list misses.
67	    let pc = polarity(claim);
68	    let mut pm = polarity(&cp.commit_message);
69	    if pm == 0 {
70	        let m = cp.commit_message.to_lowercase();
71	        if m.starts_with("feat") || m.starts_with("fix") || m.starts_with("perf") {
72	            pm = 1;
73	        } else if m.starts_with("revert") {
74	            pm = -1;
75	        }
76	    }
77	    let commit_terms = terms(&cp.commit_message);
78	    if pc != 0 && pm != 0 && pc != pm && claim_terms.intersection(&commit_terms).count() >= 1 {
79	        return (
80	            Agree::Contradicted,
81	            "action polarity opposes the commit".into(),
82	        );
83	    }
84	
85	    // 4. M1 identifier anchor: a code-shaped token the diff never contains.
86	    if let Some(ident) = missing_identifier(claim, cp) {
87	        return (
88	            Agree::Contradicted,
89	            format!("names {ident}, which the change does not contain"),
90	        );
91	    }
92	
93	    // 5. Lexical agreement with what the commit says it did.
94	    let shared = claim_terms.intersection(&commit_terms).count();
95	    if shared >= LEXICAL_MIN_SHARED {
96	        return (
97	            Agree::Corroborated,
98	            format!("{shared} terms match commit subject"),
99	        );
100	    }
101	
102	    // 6. Character 4-gram cosine against the diff and file names.
103	    let corpus = format!(
104	        "{} {} {}",
105	        cp.commit_message,
106	        cp.files.join(" "),
107	        cp.diff.join(" ")
108	    );
109	    let sim = cosine(&ngrams(claim), &ngrams(&corpus));
110	    if sim > NGRAM_THRESHOLD {
111	        return (
112	            Agree::Corroborated,
113	            format!("4-gram cosine {sim:.3} with the change"),
114	        );
115	    }
116	
117	    (Agree::Neutral, "no overlap with commit subject".into())
118	}
119	
120	/// M1 — identifier anchoring. Words that look like code are hard claims: if
121	/// the message names one and the diff never contains any of its pieces, the
122	/// message is lying about the code. Returns the first offending token.
123	fn missing_identifier(claim: &str, cp: &Checkpoint) -> Option<String> {
124	    let v = diff_vocab(cp);
125	    for raw in claim.split(|ch: char| ch.is_whitespace() || ch == '`' || ch == ',' || ch == ':') {
126	        let w = raw.trim_matches(|ch: char| {
127	            !ch.is_alphanumeric() && ch != '_' && ch != '.' && ch != '(' && ch != ')'
128	        });
129	        if w.len() < 5 || !code_shaped(w) {
130	            continue;
131	        }
132	        let parts = split_ident(w);
133	        if !parts.is_empty() && parts.iter().all(|p| !v.contains(p)) {
134	            return Some(w.to_string());
135	        }
136	    }
137	    None
138	}
139	
140	const TLDS: &[&str] = &[".com", ".io", ".dev", ".org", ".net", ".ai", ".co"];
141	
142	/// A term is URL-shaped when it carries a scheme, a `www.` host, or a
143	/// TLD-looking suffix on its first segment. `terms()` splits on `:` so a URL
144	/// arrives as `https` plus `//host/path...`; the leading `//` marks the latter.
145	fn looks_like_url(t: &str) -> bool {
146	    if t.contains("://") || t.starts_with("//") || t.starts_with("www.") {
147	        return true;
148	    }
149	    let host = t.split('/').next().unwrap_or(t);
150	    TLDS.iter()
151	        .any(|tld| host.ends_with(tld) || host.contains(&format!("{tld}/")))
152	        || TLDS.iter().any(|tld| t.contains(&format!("{tld}/")))
153	}

